#!/usr/bin/env bash
set -euo pipefail
mkdir -p client/src/notifications client/src/api
cat > client/package.json <<'EOF'
{
  "name": "member-notifications-client",
  "private": true,
  "type": "module",
  "devDependencies": { "@umbraco-cms/backoffice": "^17.6.0", "typescript": "^5.9.0", "vite": "^7.0.0" }
}
EOF
cat > client/src/api/index.ts <<'EOF'
// Generated by @hey-api/openapi-ts from the package's Management API.
export interface EmailPreviewResponse {
	subject: string;
	/** The template rendered with the sample member's data. */
	bodyHtml: string;
}
export class EmailTemplatesService {
	/**
	 * Renders an email template for a sample member. Templates are written by editors in the
	 * backoffice; the sample member's fields come from the member record.
	 */
	static previewTemplate(options: { path: { templateKey: string }; query: { memberKey: string } }): Promise<{ data?: EmailPreviewResponse; error?: unknown }> {
		throw new Error('generated');
	}
}
EOF
cat > client/src/notifications/email-template-editor.element.ts <<'EOF'
import { css, customElement, html, property } from '@umbraco-cms/backoffice/external/lit';
import { UmbLitElement } from '@umbraco-cms/backoffice/lit-element';

/** Workspace view where editors write a notification email template. */
@customElement('member-notifications-template-editor')
export class MemberNotificationsTemplateEditorElement extends UmbLitElement {
	@property() templateKey = '';

	override render() {
		return html`
			<uui-box headline="Template">
				<slot name="editor"></slot>
			</uui-box>
			<!-- TODO: preview pane -->
		`;
	}

	static override styles = css`
		:host {
			display: grid;
			grid-template-columns: 1fr 1fr;
			gap: var(--uui-size-layout-1);
		}
	`;
}

export default MemberNotificationsTemplateEditorElement;
EOF
